### Task: Write a Python function to check if a number is prime.
### Input: None
### Output:
def is_prime(num):
    if num <= 1:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

### Task: Write a program to find the factorial of a number.
### Input: None
### Output: 
def factorial(n):
    if n == 0:
        return 1
    else:
        return n * factorial(n-1)

### Task: Design a basic chatbot that can perform arithmetic operations.
### Input: None
### Output: 
class ArithmeticChatbot:
    def __init__(self):
        self.operations = {'add': self.add, 'subtract': self.subtract, 'multiply': self.multiply, 'divide': self.divide}

    def add(self, a, b):
        return a + b

    def subtract(self, a, b):
        return a - b

    def multiply(self, a, b):
        return a * b

    def divide(self, a, b):
        return a / b if b != 0 else 'Cannot divide by zero'

    def chat(self, operation, a, b):
        if operation in self.operations:
            return self.operations[operation](a, b)
        else:
            return 'Operation not supported'

# Example usage:
bot = ArithmeticChatbot()
print(bot.chat('add', 5, 3))  # Output: 8

### Task: Write a function to calculate the factorial of a number.
### Input: A positive integer, n
### Output: 
def factorial(n):
    if n == 0 or n == 1:
        return 1
    else:
        return n * factorial(n-1)
